#ifndef INVENTORY_H
#define INVENTORY_H

#include <map>
#include <string>
#include <vector>

// Stock of the hostel mess store. Quantities are whole units (kg, packets, litres).
class Inventory {
public:
    // Adds qty (> 0) to the item, creating it if new. Returns the new stock.
    int receive(const std::string& item, int qty);
    // Takes qty out. Returns false, and changes nothing, if the item is unknown or short.
    bool issue(const std::string& item, int qty);
    // Stock of an item (0 if unknown).
    int stock(const std::string& item) const;
    // Reorder level for an item: LOW lists items whose stock is below it.
    void setReorder(const std::string& item, int level);
    // "<item> <stock>/<level>" for every item below its level, sorted by item name.
    std::vector<std::string> low() const;

private:
    std::map<std::string, int> stock_;
    std::map<std::string, int> reorder_;
};

#endif

