#include <iostream>
#include <sstream>
#include <string>
#include "inventory.h"
using namespace std;

static bool positive(const string& s, int& out) {
    if (s.empty() || s.size() > 6 || s.find_first_not_of("0123456789") != string::npos || s[0] == '0') return false;
    out = stoi(s);
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    Inventory inv;
    string line;
    while (getline(cin, line)) {
        istringstream in(line);
        string cmd, item, num, extra;
        if (!(in >> cmd)) continue;
        in >> item >> num;
        bool more = static_cast<bool>(in >> extra);
        int qty = 0;
        if (cmd == "RECEIVE" && !more && positive(num, qty)) cout << item << " stock " << inv.receive(item, qty) << "\n";
        else if (cmd == "ISSUE" && !more && positive(num, qty)) {
            if (inv.issue(item, qty)) cout << item << " stock " << inv.stock(item) << "\n";
            else cout << "error: only " << inv.stock(item) << " " << item << " in stock\n";
        } else if (cmd == "REORDER" && !more && positive(num, qty)) {
            inv.setReorder(item, qty);
            cout << item << " reorder at " << qty << "\n";
        } else if (cmd == "LOW" && item.empty()) {
            auto rows = inv.low();
            if (rows.empty()) cout << "nothing to reorder\n";
            for (const auto& r : rows) cout << r << "\n";
        } else cout << "error: bad command " << line << "\n";
    }
    return 0;
}

