#include "inventory.h"

int Inventory::receive(const std::string& item, int qty) {
    return stock_[item] += qty;
}

bool Inventory::issue(const std::string& item, int qty) {
    auto it = stock_.find(item);
    if (it == stock_.end() || it->second < qty) return false;
    it->second -= qty;
    return true;
}

int Inventory::stock(const std::string& item) const {
    auto it = stock_.find(item);
    return it == stock_.end() ? 0 : it->second;
}

void Inventory::setReorder(const std::string& item, int level) {
    reorder_[item] = level;
}

std::vector<std::string> Inventory::low() const {
    std::vector<std::string> out;
    for (const auto& [item, level] : reorder_) {   // std::map iterates in key order
        int have = stock(item);
        if (have < level) out.push_back(item + " " + std::to_string(have) + "/" + std::to_string(level));
    }
    return out;
}
